using System.Text.Json;
namespace RealmGate.Server;
public enum RuntimeAdministrativePermission { Inspect, Teleport, Summon, Spawn, Despawn, Kill, Heal, GrantItem, GrantCurrency, GrantExperience, SetLevel, SetFlags, Reset, EventControl, Broadcast, Moderate, Ban, Freeze, SaveWorld, ReloadData, InspectRuntime, Trace }
public enum RuntimeAdministrativeActionState { Requested, Authorized, Dispatched, Completed, Rejected, Failed, RolledBack }
public sealed record RuntimeAdministrativeActor(string ActorId,int AuthorityLevel,IReadOnlySet<RuntimeAdministrativePermission> Permissions,bool IsHostOperator);
public sealed record RuntimeAdministrativeActionDefinition(string Id,RuntimeAdministrativePermission Permission,int MinimumAuthority,string OwnerSubsystem,bool RequiresConfirmation,bool SupportsRollback,bool MutatesCharacterSave,bool MutatesWorldState);
public sealed record RuntimeAdministrativeRequest(string RequestId,string ActionId,string ActorId,string? TargetId,IReadOnlyDictionary<string,string> Arguments,bool Confirmed,DateTimeOffset RequestedUtc);
public sealed record RuntimeAdministrativeDispatch(string RequestId,string OwnerSubsystem,string ActionId,string? TargetId,IReadOnlyDictionary<string,string> Arguments,long Sequence,bool SupportsRollback,bool MutatesCharacterSave,bool MutatesWorldState);
public sealed record RuntimeAdministrativeAuditEntry(string RequestId,string ActionId,string ActorId,string? TargetId,RuntimeAdministrativeActionState State,string Code,DateTimeOffset TimestampUtc,long Sequence);
public sealed record RuntimeAdministrativeResult(bool Accepted,string Code,RuntimeAdministrativeDispatch? Dispatch,RuntimeAdministrativeAuditEntry Audit);
public sealed class RuntimeAdministrativePolicyService
{
 private readonly Dictionary<string,RuntimeAdministrativeActionDefinition> _definitions; private readonly List<RuntimeAdministrativeAuditEntry> _audit=new(); private long _sequence;
 public RuntimeAdministrativePolicyService(IEnumerable<RuntimeAdministrativeActionDefinition> definitions){_definitions=new(StringComparer.OrdinalIgnoreCase);foreach(var d in definitions){if(string.IsNullOrWhiteSpace(d.Id)||string.IsNullOrWhiteSpace(d.OwnerSubsystem)||d.MinimumAuthority<0)throw new ArgumentException("invalid-administrative-action");if(!_definitions.TryAdd(d.Id,d))throw new ArgumentException("duplicate-administrative-action");}}
 public IReadOnlyList<RuntimeAdministrativeAuditEntry> Audit=>_audit;
 public RuntimeAdministrativeResult Authorize(RuntimeAdministrativeActor actor,RuntimeAdministrativeRequest request,DateTimeOffset now)
 {if(!_definitions.TryGetValue(request.ActionId,out var d))return Reject(request,"unknown-action",now);if(!actor.IsHostOperator)return Reject(request,"host-operator-required",now);if(actor.AuthorityLevel<d.MinimumAuthority)return Reject(request,"insufficient-authority",now);if(!actor.Permissions.Contains(d.Permission))return Reject(request,"permission-denied",now);if(d.RequiresConfirmation&&!request.Confirmed)return Reject(request,"confirmation-required",now);if(string.IsNullOrWhiteSpace(request.RequestId)||string.IsNullOrWhiteSpace(actor.ActorId)||!string.Equals(actor.ActorId,request.ActorId,StringComparison.OrdinalIgnoreCase))return Reject(request,"actor-mismatch",now);var seq=++_sequence;var dispatch=new RuntimeAdministrativeDispatch(request.RequestId,d.OwnerSubsystem,d.Id,request.TargetId,new Dictionary<string,string>(request.Arguments,StringComparer.OrdinalIgnoreCase),seq,d.SupportsRollback,d.MutatesCharacterSave,d.MutatesWorldState);var audit=new RuntimeAdministrativeAuditEntry(request.RequestId,d.Id,actor.ActorId,request.TargetId,RuntimeAdministrativeActionState.Dispatched,"authorized",now,seq);_audit.Add(audit);return new(true,"authorized",dispatch,audit);}
 public RuntimeAdministrativeAuditEntry Complete(string requestId,string actionId,string actorId,string? targetId,bool success,bool rolledBack,string code,DateTimeOffset now){var state=rolledBack?RuntimeAdministrativeActionState.RolledBack:success?RuntimeAdministrativeActionState.Completed:RuntimeAdministrativeActionState.Failed;var a=new RuntimeAdministrativeAuditEntry(requestId,actionId,actorId,targetId,state,code,now,++_sequence);_audit.Add(a);return a;}
 public IReadOnlyList<string> ValidateState(){var e=new List<string>();if(_audit.Select(x=>x.Sequence).Distinct().Count()!=_audit.Count)e.Add("duplicate-audit-sequence");if(_audit.Any(x=>string.IsNullOrWhiteSpace(x.RequestId)||string.IsNullOrWhiteSpace(x.ActorId)||string.IsNullOrWhiteSpace(x.ActionId)))e.Add("invalid-audit-entry");return e;}
 private RuntimeAdministrativeResult Reject(RuntimeAdministrativeRequest r,string code,DateTimeOffset now){var a=new RuntimeAdministrativeAuditEntry(r.RequestId,r.ActionId,r.ActorId,r.TargetId,RuntimeAdministrativeActionState.Rejected,code,now,++_sequence);_audit.Add(a);return new(false,code,null,a);}
}
